import "server-only";
import fs from "node:fs/promises";
import path from "node:path";

/**
 * Private file storage on the server's disk (outside /public, so files are only reachable through
 * authorised routes). Keys are generated by the app, never taken from user input.
 */
// The hint stops the build from tracing the whole project because of the dynamic paths below.
const ROOT = path.resolve(/* turbopackIgnore: true */ process.cwd(), process.env.STORAGE_DIR ?? "storage");

function resolveKey(key: string) {
  if (!/^[a-zA-Z0-9/_.-]+$/.test(key) || key.includes("..") || key.startsWith("/")) throw new Error("Invalid storage key");
  const full = path.resolve(ROOT, key);
  if (!full.startsWith(ROOT + path.sep)) throw new Error("Invalid storage key");
  return full;
}

export async function putFile(key: string, data: Buffer) {
  const full = resolveKey(key);
  await fs.mkdir(path.dirname(full), { recursive: true });
  await fs.writeFile(full, data);
}

export async function getFile(key: string) {
  return fs.readFile(resolveKey(key));
}

export async function deleteFile(key: string) {
  await fs.rm(resolveKey(key), { force: true });
}

export async function fileExists(key: string) {
  try {
    await fs.access(resolveKey(key));
    return true;
  } catch {
    return false;
  }
}

/** Every stored key under a prefix such as "proposals" (used by the retention sweep). */
export async function listFiles(prefix: string): Promise<string[]> {
  const base = resolveKey(prefix);
  try {
    const entries = await fs.readdir(base, { recursive: true, withFileTypes: true });
    return entries.filter((e) => e.isFile()).map((e) => path.relative(ROOT, path.join(e.parentPath, e.name)).split(path.sep).join("/"));
  } catch (e) {
    if ((e as NodeJS.ErrnoException).code === "ENOENT") return [];
    throw e;
  }
}

/** Writes and removes a probe file, to confirm the storage directory is usable. */
export async function checkStorageWritable() {
  const key = `.health/${process.pid}-${Date.now()}`;
  await putFile(key, Buffer.from("ok"));
  await deleteFile(key);
  return ROOT;
}

/** Last-modified time in ms, or null when the file does not exist. */
export async function fileModifiedAt(key: string) {
  try {
    return (await fs.stat(resolveKey(key))).mtimeMs;
  } catch {
    return null;
  }
}
